 const metric=(...args)=>cardMetric(...args),fmtDate=d=>d?d.split('-').reverse().join('.'):'Не назначена';
 const link=(url,label)=>safeUrl(url)?`<a class="source-link" href="${e(safeUrl(url))}" target="_blank" rel="noopener noreferrer">${e(label)}</a>`:'—';
 const financeFields=()=>{const s=S(),w=W();return `<div class="form-grid">${[['Заказов в день','orders'],['Средний чек, ₽','check'],['Рабочих дней','days'],['Ингредиенты / заказ, ₽','ingredients'],['Упаковка / заказ, ₽','pack'],['Прочие переменные / заказ, ₽','otherVariable'],['Эквайринг, %','acquiring'],['Налог, % (допущение)','tax']].map(([label,k])=>f(label,`finance.${k}`,s.finance[k],'number',k==='days'?'min="1" max="31" step="1"':k==='orders'?'step="1"':/tax|acquiring/.test(k)?'max="100"':'')).join('')}</div>${note(`Режим: ${w.links.recipe?'средний заказ из техкарт':'ручной средний заказ'}. ${w.links.recipe?'Редактирование чека, сырья или упаковки отключит связь с техкартами.':'Утверждённая стартовая модель сохранена. Связь с техкартами включается отдельной кнопкой.'}`)}`};
 function readiness(){const s=S(),w=W(),hasLoc=s.locations.some(l=>w.locationMeta[l.id]?.stage==='chosen');const gates=[['Локация выбрана',hasLoc,'locations'],['Продукт протестирован',!!w.decisions.productTest,'recipes'],['Оборудование получено',s.equipment.length>0&&s.equipment.every((_,i)=>w.equipmentMeta[i]?.status==='delivered'),'equipment'],['Условия партнёров согласованы',!!w.partnership.approved,'partnership'],['Тестовая смена пройдена',s.done.includes(18),'roadmap']];return gates}
 const oldDash=ctx.pages.dashboard;
 ctx.pages.dashboard=()=>{const s=S(),w=W(),g=readiness(),done=s.done.length,next=s.tasks.map((t,i)=>({t,i,m:w.taskMeta[i]})).filter(x=>!s.done.includes(x.i)).sort((a,b)=>a.m.offset-b.m.offset).slice(0,3);const block=`<div class="work-command"><div><strong>Готовность к открытию: ${g.filter(x=>x[1]).length} из ${g.length} контрольных условий</strong><small>Задачи: ${done}/${s.tasks.length}. Дата открытия: ${fmtDate(w.openingDate)}</small></div><button class="tiny-button" data-page="roadmap">Открыть план</button></div><div class="grid grid-2 work-space">${card('Ближайшие действия',`<div class="next-actions">${next.map(x=>`<button data-page="roadmap"><span class="status-chip">${w.openingDate?fmtDate(dueDate(w.openingDate,x.m)):'Д'+x.m.offset}</span>${e(x.t)}</button>`).join('')}</div>`)}${card('Что ещё требует решения',`<div class="gate-list">${g.map(([label,ready,page])=>`<button data-page="${page}"><span class="gate ${ready?'ready':''}">${ready?'✓':'○'}</span>${label}<small>${ready?'Готово':'Осталось'}</small></button>`).join('')}</div>`)}</div>`;return oldDash().replace('<div class="dashboard-kpis">',block+'<div class="dashboard-kpis">')+fold('План доработки проекта и отложенные решения',`<div class="table-wrap"><table class="table"><thead><tr><th>Раздел</th><th>Согласованная задача</th><th>Статус</th></tr></thead><tbody>${planSections.map(([id,label,task,status])=>`<tr><td><button class="text-button" data-page="${id}">${label}</button></td><td>${task}</td><td>${status}</td></tr>`).join('')}</tbody></table></div>${note('Следующий совместный этап: конкуренты по картам; полный бренд и меню; объявления помещений; реальные предложения на оборудование; тест приготовления и условия партнёров.')}`)};
 ctx.pages.strategy=()=>head('Стратегия и концепция','Первая компактная точка в Набережных Челнах: понятный продукт, заметная подача и управляемая экономика.')+`<div class="hero"><div><div class="eyebrow">РАБОЧАЯ СТРАТЕГИЯ</div><h1>Цвет привлекает.<br><em>Вкус возвращает.</em></h1><p>Цветная шаурма с разными соусами на общей куриной основе. Начинаем с одной точки и измеряем повторные покупки, скорость и фактическую себестоимость.</p></div><div class="product-art"><img src="./assets/hero-shawarma.png" alt="Цветная шаурма SHAURMA LAB"></div></div>`+
 section('Кому и зачем мы нужны')+`<div class="grid grid-3">${[['Обед рядом с работой','Сотрудники магазинов, офисов и сервисов рядом. Нужны сытность, понятная цена и предсказуемая скорость.','Повод вернуться: стабильная порция и удобный заказ.'],['Перекус по пути','Посетители ТЦ, жители района и люди в дороге. Решение принимают у витрины или по картам.','Повод купить: заметное меню, видимый состав и чистая точка.'],['Попробовать новое','Гости, которым интересны необычные вкусы и яркая подача. Возрастные рамки пока не задаём без исследования.','Повод поделиться: цветная линейка и красивая упаковка.']].map(([t,p,a])=>card(t,`<p>${p}</p><strong>${a}</strong>`)).join('')}</div>`+
 section('Формат первой точки')+`<div class="grid grid-2">${card('Компактная кухня + выдача',bullets(['Предпочтительно 25–45 м²; большая площадь оправдана только экономикой.','Основной канал — заказ на месте и навынос. Посадка — по реальному помещению.','Доставка — отдельный сценарий после проверки скорости, упаковки и комиссии.','Часы работы определяем по потоку; 12 часов — стартовое допущение графика.']))}${card('Ограниченная линейка',bullets(['Четыре цветных вкуса + классика как рабочая продуктовая гипотеза.','Общая мясная база и овощи, разные соусы и добавки.','Напитки и комбо разрабатываем отдельно вместе с полным меню.','Чек 580 ₽ остаётся ручной гипотезой модели до проверки корзины.']))}</div>`+
 section('Почему гость выберет нас')+`<div class="grid grid-3">${[['Узнаваемость','Витрина и фотографии позволяют сразу понять идею. Каждый цвет связан со вкусом.'],['Предсказуемость','Граммовки, состав и цена понятны до заказа. Продукт одинаков в разные смены.'],['Скорость и чистота','Подготовленные компоненты, понятная очередь, аккуратная упаковка. Время выдачи измеряем на тесте.']].map(([t,p])=>card(t,`<p>${p}</p>`)).join('')}</div>`+
 section('Проверяем до масштабирования')+`<div class="grid grid-2">${card('Экономика точки',bullets(['Считать сырьё и упаковку отдельно от ФОТ и аренды.','Контролировать фактические списания и выход мяса.','Сравнивать 25, 35 и 50 заказов в день.','Расширять ассортимент после устойчивой работы основной линейки.']))}${card('Проверка спроса',bullets(['Собрать оценки вкуса и готовность купить по указанной цене.','Сделать короткие замеры потока по конкретному месту.','Отслеживать причины отказа, возвраты и повторные покупки.','Не заявлять статус «первые в городе» без проверки рынка.']))}</div>`;
 function ensureLocation(l){return W().locationMeta[l.id]??={url:'',photo:'',water:'unknown',drain:'unknown',vent:'unknown',power:'',stage:'shortlist',engineering:'',visit:''}}
 ctx.pages.locations=()=>{const s=S(),selected=s.locations.find(l=>l.id===s.selectedLocation)||s.locations[0];if(!selected)return head('Помещения','Добавьте первое объявление.',btn('Добавить помещение','add-location'));s.locations.forEach(ensureLocation);const meta=ensureLocation(selected),p=`workspace.locationMeta.${selected.id}`;return head('Помещения','Объявление → короткий список → осмотр → решение. Достаточно базовых данных.',btn('Добавить объявление','add-location'))+`<div class="grid grid-3">${s.locations.map(l=>{const m=ensureLocation(l);return `<article class="card location-card ${l.id===selected.id?'selected':''}"><button class="location-pick" data-action="select-location" data-id="${l.id}"><span class="pill">${({shortlist:'В подборке',visit:'На осмотр',chosen:'Выбрано',rejected:'Не подходит'})[m.stage]||'В подборке'}</span><h3>${e(l.name)}</h3><p>${e(l.address)}</p><strong class="metric lime">${money(l.rent)}</strong><p>${l.area?num(l.area)+' м²':'Площадь уточнить'} · аренда в месяц</p></button>${link(m.url,'Открыть объявление')}</article>`}).join('')}</div>`+
 section('Карточка объявления')+`<div class="card">${safeUrl(meta.photo)?`<img class="location-photo" src="${e(safeUrl(meta.photo))}" alt="Фото помещения из объявления" loading="lazy">`:''}<div class="form-grid">${f('Название',`locations.${s.locations.indexOf(selected)}.name`,selected.name,'text')}${f('Адрес',`locations.${s.locations.indexOf(selected)}.address`,selected.address,'text')}${f('Площадь, м²',`locations.${s.locations.indexOf(selected)}.area`,selected.area)}${f('Аренда / месяц, ₽',`locations.${s.locations.indexOf(selected)}.rent`,selected.rent)}${f('Коммунальные / месяц, ₽',`locations.${s.locations.indexOf(selected)}.utility`,selected.utility)}${f('Ссылка на Авито или другое объявление',p+'.url',meta.url,'url')}${select('Этап выбора',p+'.stage',meta.stage,[['shortlist','В подборке'],['visit','Хочу осмотреть'],['chosen','Выбрано'],['rejected','Не подходит']])}${f('Дата осмотра',p+'.visit',meta.visit,'date')}${f('Фото · необязательная ссылка',p+'.photo',meta.photo,'url')}${f('Электрическая мощность · что известно',p+'.power',meta.power,'text')}</div><div class="form-grid">${[['water','Водоснабжение'],['drain','Канализация'],['vent','Вытяжка']].map(([k,t])=>select(t,p+'.'+k,meta[k],[['unknown','Неизвестно'],['yes','Есть · проверить'],['no','Нет'],['solution','Решение нужно проверить']])).join('')}</div>${area('Короткие заметки по объявлению',`locations.${s.locations.indexOf(selected)}.notes`,selected.notes)}${area('Что проверить / возможное инженерное решение',p+'.engineering',meta.engineering)}<div class="work-actions">${btn('Использовать аренду и коммунальные в модели','apply-location',`data-id="${selected.id}"`,false)}${btn('Удалить вариант','delete-location',`data-id="${selected.id}"`)}</div><p class="help">Выбор карточки — для сравнения. Расходы модели меняются только после нажатия кнопки применения. Связь: ${W().links.location===selected.id?'включена для этого помещения':'не включена'}.</p></div>`+
 fold('Короткий осмотр: что действительно нужно',bullets(['Влезают ли хранение, подготовка, приготовление, мойка и выдача без пересечения грязного и готового продукта?','Подтверждены ли вода, отведение стоков, мощность и возможность установки нужной вытяжки?','Можно ли разместить выбранный мангал и куда отводятся дым и тепло? Тип мангала ещё нужно определить.','Бойлер решает нагрев воды, но не заменяет водоснабжение. Ёмкости и другие автономные решения требуют отдельной технической и санитарной оценки.','Зафиксировать аренду, депозит, доступ, вывеску, часы работы и дополнительные платежи.']))+note('Выбираем практично: сначала подходящее объявление и базовые условия, затем осмотр лучших вариантов. Неизвестные коммуникации не считаем готовыми.')};
 function ensureEquipment(i){return W().equipmentMeta[i]??={qty:1,model:'',supplier:'',url:'',delivery:0,status:'planned',note:''}}
 ctx.pages.equipment=()=>{const s=S();s.equipment.forEach((_,i)=>ensureEquipment(i));return head('Оборудование','Согласованный ориентир — 300 000 ₽. Количество, модели и предложения заполняем по мере подбора.',btn('Добавить позицию','add-equipment'))+`<div class="grid grid-3">${metric('Бюджет оборудования',money(total(s.equipment)),'Все позиции','lime')}${metric('Доставка сверх позиций',money(W().equipmentMeta.reduce((n,m)=>n+clamp(m?.delivery),0)),'Показывается отдельно; можно перенести в смету')}${metric('Получено',s.equipment.filter((_,i)=>ensureEquipment(i).status==='delivered').length+' / '+s.equipment.length,'Статусы обновляются вручную')}</div><div class="work-space">${s.equipment.map((r,i)=>{const m=ensureEquipment(i),p=`workspace.equipmentMeta.${i}`;return fold(`${e(r[0])} · ${money(r[1])} · ${{planned:'Подобрать',selected:'Выбрано',ordered:'Заказано',delivered:'Получено'}[m.status]||'Подобрать'}`,`<div class="form-grid">${f('Позиция',`equipment.${i}.0`,r[0],'text')}${f('Бюджет всей позиции, ₽',`equipment.${i}.1`,r[1])}${f('Количество, шт. / комплектов',p+'.qty',m.qty,'number','min="1" step="1"')}${f('Модель / комплект',p+'.model',m.model,'text')}${f('Поставщик',p+'.supplier',m.supplier,'text')}${f('Ссылка на предложение',p+'.url',m.url,'url')}${f('Доставка отдельно, ₽',p+'.delivery',m.delivery)}${select('Статус',p+'.status',m.status,[['planned','Подобрать'],['selected','Выбрано'],['ordered','Заказано'],['delivered','Получено']])}</div>${area('Примечание',`equipment.${i}.2`,r[2])}${link(m.url,'Предложение поставщика')}<p class="help">Бюджет относится ко всей позиции, количество служит для комплектации.</p>${btn('Удалить позицию','delete-equipment',`data-index="${i}"`)}`)}).join('')}</div><div class="work-actions">${btn(W().links.equipment?'Связь со сметой включена · отключить':'Связать итог со сметой','toggle-equipment-link')}${btn('Добавить доставку в смету','delivery-budget')}${btn('Вернуть стартовые 300 000 ₽','reset-equipment')}</div>`+note('Для мангала уточним топливо, мощность, вытяжку и допустимость установки в выбранном помещении. Вентиляционный монтаж и сам вытяжной зонт проверим на отсутствие двойного учёта.')};
 ctx.pages.budget=()=>{const s=S(),t=total(s.budget),paid=s.budget.reduce((n,r,i)=>n+clamp(W().budgetPaid[i],0,r[1]),0);return head('Смета открытия','План вложений и оплаченные суммы. Оборотный резерв остаётся деньгами, а не расходом на оборудование.')+`<div class="grid grid-4">${metric('План',money(t),'Текущая инвестиционная смета','lime')}${metric('Оплачено',money(paid),'Отметки по статьям')}${metric('Осталось по плану',money(t-paid),'Включая ещё не сформированный резерв')}${metric('Доступное финансирование',money(s.partnership.investment),'Указывается в партнёрстве')}</div>`+section('Статьи открытия')+`<div class="card table-wrap"><table class="table"><thead><tr><th>Статья</th><th>План, ₽</th><th>Оплачено, ₽</th><th>Осталось</th><th></th></tr></thead><tbody>${s.budget.map((r,i)=>`<tr><td>${f('',`budget.${i}.0`,r[0],'text',r[0]==='Кухонное оборудование'&&W().links.equipment?'readonly':'')}${r[0]==='Кухонное оборудование'&&W().links.equipment?'<small>Связано с оборудованием</small>':''}</td><td>${f('',`budget.${i}.1`,r[1],'number',r[0]==='Кухонное оборудование'&&W().links.equipment?'readonly':'')}</td><td>${f('',`workspace.budgetPaid.${i}`,W().budgetPaid[i]||0,'number',`max="${r[1]}"`)}</td><td>${money(r[1]-clamp(W().budgetPaid[i],0,r[1]))}</td><td>${btn('Удалить','delete-budget',`data-index="${i}"`)}</td></tr>`).join('')}</tbody></table><div class="work-actions">${btn('Добавить статью','add-budget')}</div></div>`+note(`Разница между сметой и финансированием: ${money(t-s.partnership.investment)}. Доставку, монтаж и первый запас продуктов учитываем один раз. «Оплачено» — статус подготовки, а прогноз денежных потоков использует полную плановую смету.`)};
 function priceBlock(){return fold('Цены и источники · проверено 23.11.2026',note('Это открытые розничные ориентиры без выбранного адреса в Челнах. Не подтверждены местное наличие и абсолютный минимум по всем сетям. Цветной лаваш, готовый соус, специи и зелень пока оценены вручную.')+`<div class="form-grid">${Object.entries(priceLabels).map(([key,label])=>f(label+', ₽/кг',`workspace.prices.${key}`,W().prices[key])).join('')}</div><div class="work-actions">${btn('Розничное сравнение · 519,99 ₽/кг','meat-base')}${btn('Найденный минимум курицы · 289 ₽/кг','meat-low')}</div><div class="table-wrap"><table class="table"><thead><tr><th>Продукт</th><th>Магазин / товар</th><th>Цена</th><th>Основание</th></tr></thead><tbody>${offers.map(o=>`<tr><td>${e(o.item)}</td><td>${link(o.url,o.store)}<small class="block">${e(o.product)}</small></td><td class="nowrap">${num(o.price)} ${o.unit}</td><td>${e(o.note)}</td></tr>`).join('')}</tbody></table></div>`+note('Чижик: найдено бедро на кости, оно не сопоставимо с бескостным филе без измерения выхода. Находка: проверяемую актуальную цену нужного сырья в открытом каталоге получить не удалось. Оптовые условия запросим отдельно: они не обязательно ниже разовой розничной акции.'))}
 ctx.pages.recipes=()=>{const s=S(),prices=W().prices,mix=weightedRecipe(s);return head('Техкарты и себестоимость','Расчётные рецептуры для тестовой кухни. Учитываем массу готового компонента, выход сырья и упаковку.',btn('Добавить техкарту','add-recipe'))+note('Рецептуры не утверждены производственной проработкой. Выход мяса 70% — изменяемое допущение для расчёта, его нужно измерить на выбранном оборудовании.')+`<div class="grid grid-3 work-space">${s.recipes.map(r=>{const c=costing(r,prices);return card(e(r.name),`<div class="recipe-color swatch-${['green','black','red','yellow','white','purple'].includes(r.color)?r.color:'white'}"></div><div class="recipe-stats"><span>Цена: <b>${money(r.price)}</b></span><span>Сырьё и потери: <b>${money(c.food+c.waste)}</b></span><span>С упаковкой: <b>${money(c.all)}</b></span><span>Фудкост сырья: <b>${num(c.foodPct)}%</b></span><span>С упаковкой / цена: <b class="${c.fullPct>40?'cost-high':''}">${num(c.fullPct)}%</b></span><span>Цена для 40% с упаковкой: <b>${money(Math.ceil(c.targetPrice/10)*10)}</b></span></div>${btn('Состав и расчёт','edit-recipe',`data-id="${r.id}"`)}`)}).join('')}</div>`+
 (selectedRecipe?recipeEditor(selectedRecipe):'')+fold('Сравнение: найденный минимум и обычная розница',`<p>Остальные компоненты и выход мяса одинаковы. Минимум 289 ₽/кг найден в открытой карточке, но не подтверждён в магазине Челнов.</p><div class="table-wrap"><table class="table"><thead><tr><th>Блюдо</th><th>Курица 289 ₽/кг · с упаковкой</th><th>Курица 519,99 ₽/кг · с упаковкой</th></tr></thead><tbody>${s.recipes.map(r=>{const low=costing(r,{...prices,chicken:289}),base=costing(r,{...prices,chicken:519.99});return `<tr><td>${e(r.name)}</td><td>${money(low.all)} / ${num(low.fullPct)}%</td><td>${money(base.all)} / ${num(base.fullPct)}%</td></tr>`}).join('')}</tbody></table></div>`)+priceBlock()+fold('Как получить честные цифры',bullets(['«Нетто» — сколько готового компонента кладём в порцию. «Выход» — доля массы от закупленного сырья; брутто = нетто / выход.','Курицу считаем по сырой закупке: при выходе 70% для 130 г готового мяса требуется около 186 г филе.','Потери при жарке уже учтены выходом. Дополнительные списания 3% — отдельное допущение, применяемое только к продуктам, не к упаковке.','Фудкост сырья и доля себестоимости с упаковкой показаны отдельно. Аренда, зарплата и налоги учитываются в финансовой модели.','Для рецептур соусов нужны отдельные проработки. Цена смеси 350 ₽/кг — оценка, а не найденный готовый фирменный соус.']))+
 section('Связь с финансовой моделью')+`<div class="card"><p>По долям продаж из карточек: средняя цена ${money(mix?.price||0)}, сырьё ${money(mix?.food||0)}, упаковка ${money(mix?.pack||0)}. Это корзина из одной шаурмы, без напитков и комбо.</p><div class="form-grid">${s.recipes.map((r,i)=>f(e(r.name)+' · вес в продажах',`recipes.${i}.share`,r.share??0)).join('')}</div><div class="work-actions">${btn(W().links.recipe?'Отключить связь с моделью':'Применить корзину техкарт к модели','toggle-recipe-link','',false)}${btn('Отметить тест продукта','toggle-product-test')}</div><p class="help">${W().links.recipe?'Расчёты модели обновляются от рецептур.':'Ручной чек 580 ₽ и ингредиенты 240 ₽ сохранены до включения связи.'} Доли нормируются; общая сумма сейчас ${num(mix?.share||0)}. Тест продукта: ${W().decisions.productTest?'отмечен выполненным':'ещё не подтверждён'}.</p></div>`};
 function recipeEditor(id){const r=S().recipes.find(r=>r.id===id);if(!r)return '';const index=S().recipes.indexOf(r),p=`recipes.${index}`,c=costing(r,W().prices);return `<div class="card work-space recipe-editor" id="recipe-details"><div class="row"><h2>${e(r.name)}</h2>${btn('Свернуть','close-recipe')}</div><div class="form-grid">${f('Название',p+'.name',r.name,'text')}${f('Цена продажи, ₽',p+'.price',r.price)}${f('Упаковка, ₽',p+'.pack',r.pack)}${f('Дополнительные списания, %',p+'.loss',r.loss,'number','max="100"')}${f('Вес в продажах',p+'.share',r.share??0)}</div><div class="table-wrap"><table class="table"><thead><tr><th>Компонент</th><th>Нетто, г</th><th>Выход, %</th><th>Брутто, г</th><th>Цена / кг</th><th>Стоимость</th><th></th></tr></thead><tbody>${c.lines.map((it,j)=>`<tr><td>${f('',p+`.ingredients.${j}.name`,it.name,'text')}<small>${it.priceKey?'Общая цена: '+e(priceLabels[it.priceKey]||it.priceKey):'Ручная цена'}</small></td><td>${f('',p+`.ingredients.${j}.grams`,it.grams)}</td><td>${f('',p+`.ingredients.${j}.yieldPct`,it.yieldPct??100,'number','min="1" max="100"')}</td><td>${num(it.gross)}</td><td>${it.priceKey?num(it.price):f('',p+`.ingredients.${j}.costKg`,it.price)}</td><td>${money(it.cost)}</td><td>${btn('×','remove-ingredient',`data-id="${id}" data-index="${j}"`)}</td></tr>`).join('')}</tbody></table></div><p>Масса компонентов при сборке: ${num(c.weight)} г. Реальный выход готовой шаурмы измеряем после пресса. Продукты ${money(c.food)} + списания ${money(c.waste)} + упаковка ${money(c.pack)} = <strong>${money(c.all)}</strong>.</p>${area('Последовательность приготовления · проект',p+'.steps',r.steps||'Описать после теста')}${area('Аллергены · проверить состав упаковок',p+'.allergens',r.allergens||'Уточнить по компонентам')}${area('Хранение и реализация · требует проработки',p+'.storage',r.storage||'Уточнить по технологии и документам сырья')}<div class="work-actions">${btn('Добавить компонент','add-ingredient',`data-id="${id}"`)}${btn('Удалить техкарту','delete-recipe',`data-id="${id}"`)}</div></div>`}
 ctx.pages.finance=()=>{const s=S(),w=W(),f=s.finance,c=economics(f,total(s.budget)),p=forecast(s);return head('Финансовая модель','Месячная экономика и прогноз первого года. Стартовые значения со скриншота сохранены.',btn('Вернуть стартовую модель','reset-finance'))+`<div class="grid grid-4">${metric('Выручка / месяц',money(c.rev),'При '+num(f.orders)+' заказах в день','lime')}${metric('Все переменные',money(c.variable),'Продукты, упаковка, налог, эквайринг')}${metric('Постоянные',money(c.fixed),'Включая оплату смен владельца')}${metric('Операционная прибыль',money(c.profit),'До распределения партнёрам',c.profit<0?'red':'lime')}</div>`+
 section('Продажи и себестоимость')+`<div class="card">${financeFields()}</div>`+
 fold('Постоянные расходы и труд',`<div class="form-grid">${[['Аренда, ₽','rent'],['Коммунальные, ₽','utilities'],['ФОТ сотрудников, ₽','payroll'],['Страховые начисления · допущение, ₽','insurance'],['Реклама, ₽','marketing'],['Учёт и ПО, ₽','software'],['Прочие постоянные, ₽','otherFixed'],['Смен владельца за месяц','ownerShiftDays'],['Оплата смены владельца, ₽','ownerShiftPay']].map(([t,k])=>fInput(t,k)).join('')}</div>${note(`Работа владельца учтена один раз: ${f.ownerShiftDays} × ${money(f.ownerShiftPay)} = ${money(f.ownerShiftDays*f.ownerShiftPay)}. Налоговые и страховые настройки — ваши управленческие допущения; применимость режима проверяем отдельно.`)}`)+
 section('Порог и сценарии')+`<div class="grid grid-3">${metric('Безубыточность',Number.isFinite(c.bep)?c.bep+' заказов/день':'Нет положительной маржи','При текущих расходах')}${metric('Маржа заказа',money(c.margin),'После всех переменных')}${metric('Простая окупаемость',Number.isFinite(c.payback)?num(c.payback)+' мес.':'Не окупается','Без периода разгона')}</div><div class="card work-space table-wrap"><table class="table"><thead><tr><th>Сценарий</th><th>Заказов / день</th><th>Выручка</th><th>Прибыль</th><th></th></tr></thead><tbody>${[['Осторожный',25],['Базовый',35],['Оптимистичный',50]].map(([label,n])=>{const e=economics({...f,orders:n},total(s.budget));return `<tr><td>${label}</td><td>${n}</td><td>${money(e.rev)}</td><td>${money(e.profit)}</td><td>${btn('Применить','orders-preset',`data-orders="${n}"`)}</td></tr>`}).join('')}</tbody></table><p class="help">Сравнение меняет только количество заказов. Чек и расходы берутся из текущей модели.</p></div>`+
 section('Первый год: прибыль и деньги')+`<div class="grid grid-4">${metric('Стартовый остаток',money(p.openingCash),'Финансирование минус расходы открытия')}${metric('Минимум денег за год',money(p.minCash),'До выплат партнёрам',p.minCash<0?'red':'lime')}${metric('Прибыль за 12 месяцев',money(p.annualProfit),'С учётом разгона продаж')}${metric('Возврат вложений',p.actualPayback?p.actualPayback+'-й месяц':'Позже 12 месяцев','По накопленной прибыли')}</div>`+
 fold('Настроить разгон продаж',`<p>100% = ${num(f.orders)} заказов в день. Это сценарные допущения, не прогноз спроса.</p><div class="ramp-grid">${w.projection.ramp.map((v,i)=>fInputRamp(i,v)).join('')}</div>`)+
 `<div class="card table-wrap"><table class="table forecast-table"><thead><tr><th>Месяц</th><th>Загрузка</th><th>Выручка</th><th>Переменные</th><th>Постоянные</th><th>Прибыль</th><th>Деньги на конец</th></tr></thead><tbody>${p.months.map(m=>`<tr><td>${m.month}</td><td>${num(m.factor)}%</td><td>${money(m.rev)}</td><td>${money(m.variable)}</td><td>${money(m.fixed)}</td><td class="${m.profit<0?'cost-high':''}">${money(m.profit)}</td><td class="${m.cash<0?'cost-high':''}">${money(m.cash)}</td></tr>`).join('')}</tbody></table></div>`+
 note(`Смета ${money(p.investment)} включает резерв ${money(p.reserve)}. На открытие расходуется ${money(p.startup)}; резерв не вычитается второй раз. Финансирование ${money(p.funding)}. ${p.fundingGap?'Недостаёт до полной сметы '+money(p.fundingGap)+'. ':''}Все продажи и расходы считаем оплаченными в текущем месяце. Выплаты партнёрам, кредиты, амортизация и дополнительное оборудование в этот прогноз не включены.`)+
 fold('Управленческие выводы',bullets([`Доля продуктов в чеке: ${num(f.check?f.ingredients/f.check*100:0)}%; с упаковкой ${num(f.check?(f.ingredients+f.pack)/f.check*100:0)}%. Это не доля всех расходов.`,c.margin>0?'Каждые дополнительные 5 заказов в день добавляют около '+money(c.margin*5*f.days)+' к месячной прибыли при неизменных постоянных расходах.':'Сначала нужно восстановить положительную маржу заказа.',p.minCash<0?'В сценарии есть кассовый разрыв. Нужны дополнительные деньги, более быстрый выход на продажи или снижение расходов.':'В текущем сценарии отрицательного остатка нет; перед выплатами сверяем фактическую кассу.',`Резерв покрывает примерно ${num(c.fixed?p.reserve/c.fixed:0)} месяца постоянных расходов без выручки.`]))};
 function fInput(label,key){return f(label,`finance.${key}`,S().finance[key],'number',key==='ownerShiftDays'?'max="31" step="1"':'')}
 function fInputRamp(i,v){return f('Месяц '+(i+1)+', %',`workspace.projection.ramp.${i}`,v,'number','max="200"')}
 function payout(){const s=S(),w=W(),c=economics(s.finance,total(s.budget)),work=clamp(s.partnership.managerSalary)+clamp(s.partnership.investorMonthlyWork)+clamp(s.partnership.managerMonthlyWork),available=Math.max(0,c.profit-work),reserve=available*clamp(w.partnership.reservePct,0,100)/100;return {work,available,reserve,distributable:available-reserve}}
 ctx.pages.partnership=()=>{const s=S(),w=W(),p=s.partnership,a=payout(),valid=p.investorShare+p.managerShare===100;return head('Партнёрство и выплаты','Проект правил для обсуждения. Доли 50/50 остаются расчётным вариантом, пока стороны не согласовали условия.')+`<div class="grid grid-2">${card('Инвестор',bullets(['Предоставляет согласованное финансирование и участвует в утверждении бюджета.','Помогает с закупками и логистикой по отдельной договорённости.','Получает финансовый отчёт и свою долю распределяемой прибыли.','Дополнительная работа и возврат капитала обсуждаются отдельно от долей.']))}${card('Управляющий партнёр',bullets(['Организует запуск, поставщиков, учёт и маркетинг.','Контролирует качество, команду, расходы и результат точки.','Согласовывает выход за бюджет и крупные покупки.','Смены поваром оплачиваются отдельно и уже включены в модель.']))}</div>`+
 section('Расчёт участия')+`<div class="card"><div class="form-grid">${[['Финансирование инвестора, ₽','investment'],['Доля инвестора, %','investorShare'],['Доля управляющего, %','managerShare'],['Доплата за управление, ₽/мес.','managerSalary'],['Работа инвестора, ₽/мес.','investorMonthlyWork'],['Другие работы управляющего, ₽/мес.','managerMonthlyWork']].map(([t,k])=>f(t,`partnership.${k}`,p[k],'number',k.includes('Share')?'max="100"':'')).join('')}${f('Резерв из положительного остатка, %','workspace.partnership.reservePct',w.partnership.reservePct,'number','max="100"')}${f('Минимум денег перед выплатами, ₽','workspace.partnership.minCash',w.partnership.minCash)}</div>${!valid?note('Доли должны давать в сумме 100%. Распределение до исправления не показываем.',true):''}<div class="grid grid-4">${metric('Дополнительная работа',money(a.work),'Сверх смен поваром')}${metric('Отложить в резерв',money(a.reserve),'Предлагаемая настройка')}${metric('Инвестору',valid?money(a.distributable*p.investorShare/100):'Проверьте доли','Из распределяемой прибыли')}${metric('Управляющему',valid?money(a.distributable*p.managerShare/100):'Проверьте доли','Без оплаты смен поваром')}</div></div>`+
 section('Порядок месяца · предложение')+`<div class="grid grid-2">${card('До выплаты',bullets(['Закрыть выручку, закупки, списания и обязательные платежи.','Оплатить согласованную работу; не учитывать одни смены дважды.','Отложить установленную долю положительного остатка в резерв.','Проверить, что после выплаты остаётся минимум '+money(w.partnership.minCash)+' и деньги на ближайшие обязательства.','Утвердить отчёт и сумму выплаты обеими сторонами.']))}${card('Если нужны дополнительные деньги',bullets(['Зафиксировать причину и обновлённую потребность.','Согласовать форму: дополнительный вклад, заём или иная договорённость.','Не менять доли автоматически из-за перерасхода.','Покупки вне бюджета и вывод денег согласовывать заранее.','Отдельно описать выход партнёра и принадлежность оборудования.']))}</div>`+
 `<div class="card work-space">${area('Договорённости и вопросы','partnership.notes',p.notes)}<label class="check-label"><input type="checkbox" data-write="workspace.partnership.approved" ${w.partnership.approved?'checked':''}> Условия действительно обсуждены и согласованы партнёрами</label><p class="help">Отметка фиксирует ваш статус проекта и не заменяет оформление договорённостей. Резерв 10% и минимальный остаток — предложения, а не утверждённые условия. Расчёт долей не доказывает наличие денег в кассе.</p></div>`};
